 #define NUM_CUBES 8           // Number of recursive cube layers

#define ROTATION_SPEED 0.3    // Speed of cube rotation

#define ZOOM_SPEED 0.1        // Speed of zoom effect

#define CUBE_SCALE 0.6        // Scaling factor for cube recursion

#define CUBE_SPACING 3.0      // Spacing between cube layers

#define MAX_STEPS 100         // Maximum steps for ray marching

#define MIN_DIST 0.001        // Minimum distance for ray marching

#define MAX_DIST 50.0         // Maximum distance for ray marching

// Function to generate psychedelic color gradients

vec3 psychedelicColor(float time) {

    return 0.5 + 0.5 * cos(time + vec3(0.0, 2.0, 4.0));

}

// Function to calculate the distance to a 3D cube

float cubeDistance(vec3 p, float size) {

    p = abs(p) - size;  // Reflective symmetry for cube

    return length(max(p, 0.0)) + min(max(p.x, max(p.y, p.z)), 0.0);

}

// Function to create a rotating cube grid

float rotatingCubes(vec3 p, float time) {

    // Rotate around Y-axis

    mat2 rotY = mat2(cos(time), -sin(time), sin(time), cos(time));

    p.xz *= rotY;

    // Recursive layers of cubes

    float dist = 1e10; // Start with a large distance

    for (int i = 0; i < NUM_CUBES; i++) {

        float scale = pow(CUBE_SCALE, float(i));

        vec3 pos = p * scale - vec3(0.0, 0.0, float(i) * CUBE_SPACING);

        dist = min(dist, cubeDistance(pos, 0.5));

    }

    return dist;

}

// Ray marching function

float rayMarch(vec3 rayOrigin, vec3 rayDir, float time, out vec3 hitPos) {

    float dist = 0.0;  // Current distance traveled

    for (int i = 0; i < MAX_STEPS; i++) {

        vec3 pos = rayOrigin + dist * rayDir;

        float cubeDist = rotatingCubes(pos, time);

        if (cubeDist < MIN_DIST) {

            hitPos = pos;

            return dist;

        }

        if (dist > MAX_DIST) break;

        dist += cubeDist;

    }

    hitPos = vec3(0.0);

    return -1.0;  // No hit

}

// Lighting function (Phong shading)

vec3 lighting(vec3 pos, vec3 normal, vec3 lightDir, vec3 viewDir) {

    float ambient = 0.2;

    float diffuse = max(dot(normal, lightDir), 0.0);

    vec3 reflectDir = reflect(-lightDir, normal);

    float specular = pow(max(dot(viewDir, reflectDir), 0.0), 16.0);

    return vec3(ambient + diffuse + specular);

}

// Estimate surface normal using gradient approximation

vec3 estimateNormal(vec3 p, float time) {

    vec2 e = vec2(0.001, 0.0);

    float d = rotatingCubes(p, time);

    return normalize(vec3(

        rotatingCubes(p + e.xyy, time) - d,

        rotatingCubes(p + e.yxy, time) - d,

        rotatingCubes(p + e.yyx, time) - d

    ));

}

// Procedural psychedelic background pattern

vec3 psychedelicBackground(vec2 uv, float time) {

    float wave = sin(uv.x * 10.0 + time * 2.0) * cos(uv.y * 10.0 + time * 2.0);

    wave += sin(uv.x * 5.0 - time) * cos(uv.y * 5.0 - time);

    wave = fract(wave * 3.0);

    vec3 color = 0.5 + 0.5 * cos(vec3(0.0, 2.0, 4.0) + wave * 10.0);

    return color * (0.5 + 0.5 * wave);

}

// Main shader function

void mainImage(out vec4 fragColor, in vec2 fragCoord) {

    vec2 uv = fragCoord.xy / iResolution.xy;  // Normalize coordinates

    uv = uv * 2.0 - 1.0;                      // Scale to [-1, 1]

    uv.x *= iResolution.x / iResolution.y;    // Adjust for aspect ratio

    // Camera setup

    vec3 rayOrigin = vec3(0.0, 0.0, -5.0);

    vec3 rayDir = normalize(vec3(uv, 1.5));

    // Animate rotation and zoom

    float time = iTime * ROTATION_SPEED;

    float zoom = 1.0 + sin(iTime * ZOOM_SPEED) * 0.5;

    rayOrigin *= zoom;

    // Perform ray marching

    vec3 hitPos;

    float dist = rayMarch(rayOrigin, rayDir, time, hitPos);

    // Generate color based on hit or background

    vec3 color;

    if (dist > 0.0) {

        vec3 normal = estimateNormal(hitPos, time);

        vec3 lightDir = normalize(vec3(1.0, 1.0, -1.0));  // Directional light

        vec3 viewDir = normalize(-rayDir);

        vec3 materialColor = psychedelicColor(iTime + dist * 0.1);

        color = lighting(hitPos, normal, lightDir, viewDir) * materialColor;

    } else {

        color = psychedelicBackground(uv, iTime);  // Dynamic trippy background

    }

    // Final output color

    fragColor = vec4(color, 1.0);

}
